11	/** A project the owner does for a client: a name and the owning client's id. Maps to {@code project} (V3). */
12	@Entity
13	@Table(name = "project")
14	public class Project {
15	
16	    @Id
17	    @GeneratedValue(strategy = GenerationType.IDENTITY)
18	    private Long id;
19	
20	    private String name;
21	
22	    @Column(name = "client_id")
23	    private Long clientId;
24	
25	    private boolean archived;
26	
27	    private String status;
28	
29	    /** The budget set against this project; what has been invoiced is compared to it (V23). */
30	    private BigDecimal budget;
31	
32	    public Project() {
33	    }
34	
35	    public Project(String name, Long clientId) {
36	        this(name, clientId, "ACTIVE");
37	    }
