3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // project references client via FK; H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the duration of the clear, then restore it.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE dashboard_config");
39	        jdbc.execute("TRUNCATE TABLE note RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE project_tag RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tag RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE payment RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE line_item RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    @SuppressWarnings("unchecked")
55	    public void seed(@RequestBody Map<String, Object> fixture) {
56	        Object asOf = fixture.get("asOf");
57	        if (asOf != null) {
58	            // The dashboard's reference date for deciding which SENT invoices are overdue (V24).
59	            jdbc.update("INSERT INTO dashboard_config (id, as_of) VALUES (1, ?)",
60	                    java.sql.Date.valueOf(asOf.toString()));
61	        }
62	        List<Map<String, Object>> clients =
63	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
64	        for (Map<String, Object> client : clients) {
65	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
66	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
67	        }
68	        List<Map<String, Object>> projects =
69	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
70	        for (Map<String, Object> project : projects) {
71	            Object status = project.getOrDefault("status", "ACTIVE");
72	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
73	            Object budgetValue = project.get("budget");
74	            java.math.BigDecimal budget = budgetValue == null ? java.math.BigDecimal.ZERO
75	                    : new java.math.BigDecimal(budgetValue.toString());
76	            jdbc.update(
77	                    "INSERT INTO project (id, name, client_id, status, archived, budget) "
78	                            + "VALUES (?, ?, ?, ?, ?, ?)",
79	                    ((Number) project.get("id")).longValue(), project.get("name"),
80	                    ((Number) project.get("clientId")).longValue(), status, archived, budget);
81	        }
82	        List<Map<String, Object>> tasks =
83	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
84	        for (Map<String, Object> task : tasks) {
85	            Object done = task.getOrDefault("done", Boolean.FALSE);
86	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
87	                    ((Number) task.get("id")).longValue(),
88	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
89	                    Boolean.TRUE.equals(done));
90	        }
91	        List<Map<String, Object>> notes =
92	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
93	        long maxNoteId = 0;
94	        for (Map<String, Object> note : notes) {
95	            long noteId = ((Number) note.get("id")).longValue();
96	            maxNoteId = Math.max(maxNoteId, noteId);
97	            jdbc.update(
98	                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
99	                    noteId, note.get("targetType"),
100	                    ((Number) note.get("targetId")).longValue(), note.get("text"),
101	                    java.sql.Timestamp.from(java.time.Instant.parse(note.get("at").toString())));
102	        }
103	        if (maxNoteId > 0) {
104	            // Seeding explicit ids does not advance H2's IDENTITY sequence, so a note created later
105	            // through the API would collide on id=1. Nudge the sequence past the seeded ids.
106	            jdbc.execute("ALTER TABLE note ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
107	        }
108	        List<Map<String, Object>> tags =
109	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
110	        for (Map<String, Object> tag : tags) {
111	            jdbc.update("INSERT INTO tag (id, name) VALUES (?, ?)",
112	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
113	        }
114	        List<Map<String, Object>> projectTags =
115	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
116	        for (Map<String, Object> projectTag : projectTags) {
117	            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
118	                    ((Number) projectTag.get("projectId")).longValue(),
119	                    ((Number) projectTag.get("tagId")).longValue());
120	        }
121	        List<Map<String, Object>> contacts =
122	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
123	        for (Map<String, Object> contact : contacts) {
124	            boolean primary = Boolean.TRUE.equals(contact.getOrDefault("primary", Boolean.FALSE));
125	            jdbc.update(
126	                    "INSERT INTO contact (id, client_id, name, email, role, is_primary) "
127	                            + "VALUES (?, ?, ?, ?, ?, ?)",
128	                    ((Number) contact.get("id")).longValue(),
129	                    ((Number) contact.get("clientId")).longValue(), contact.get("name"),
130	                    contact.get("email"), contact.get("role"), primary);
131	        }
132	        List<Map<String, Object>> invoices =
133	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
134	        for (Map<String, Object> invoice : invoices) {
135	            Object status = invoice.getOrDefault("status", "DRAFT");
136	            Object issuedDate = invoice.get("issuedDate");
137	            Object dueDate = invoice.get("dueDate");
138	            long invoiceId = ((Number) invoice.get("id")).longValue();
139	            // An invoice's amount is the sum of its line items (quantity times unit price); work it
140	            // out here so a fixture lists the things being charged for, not a pre-computed figure.
141	            // A fixture may still pass an explicit amount for an invoice with no line items.
142	            List<Map<String, Object>> lineItems =
143	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", null);
144	            java.math.BigDecimal amount;
145	            if (lineItems != null) {
146	                amount = java.math.BigDecimal.ZERO;
