2	import { ClientSummary } from './ClientSummary';
3	import { ClientStatement } from './ClientStatement';
4	import { ClientProjects } from './ClientProjects';
5	import { ClientContacts } from './ClientContacts';
6	
7	// The clients feature owns its own state, data loading and layout (no global store). It lists every
8	// client and adds a new one by name + email.
9	type Client = { id: number; name: string; email: string };
10	
11	// A proper email: something, '@', something, '.', something — no whitespace. Matches the server
12	// (CreateClientLogic) and schema (V2) checks so the three layers agree on what is acceptable.
13	const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
14	
15	export function ClientsPage() {
16	  const [clients, setClients] = useState<Client[]>([]);
17	  const [name, setName] = useState('');
18	  const [email, setEmail] = useState('');
19	  const [emailError, setEmailError] = useState('');
20	  const [search, setSearch] = useState('');
21	  // How the list is ordered: by name (A–Z) or by how much each client owes (most first).
22	  const [sort, setSort] = useState<'name' | 'outstanding'>('name');
23	  // Per-client outstanding totals, keyed by client id, for the "owes" ordering.
24	  const [outstanding, setOutstanding] = useState<Record<number, number>>({});
25	  const [openClientId, setOpenClientId] = useState<number | null>(null);
26	
27	  // The client currently being corrected from the list, plus the edited field values.
28	  const [editingClientId, setEditingClientId] = useState<number | null>(null);
29	  const [editName, setEditName] = useState('');
30	  const [editEmail, setEditEmail] = useState('');
31	  const [editError, setEditError] = useState('');
32	
33	  async function load() {
34	    const res = await fetch('/api/clients');
35	    setClients(await res.json());
36	    const owed = await fetch('/api/clients/outstanding');
37	    const rows: { id: number; outstanding: number }[] = await owed.json();
38	    setOutstanding(Object.fromEntries(rows.map((r) => [r.id, Number(r.outstanding)])));
39	  }
40	
41	  useEffect(() => {
42	    void load();
43	  }, []);
44	
45	  async function onSubmit(e: React.FormEvent) {
46	    e.preventDefault();
47	
48	    // Every client needs a proper email — block the save and surface the error if it is missing or
49	    // malformed, so no row is created.
50	    if (!EMAIL.test(email.trim())) {
51	      setEmailError('A proper email address is required');
52	      return;
53	    }
54	    setEmailError('');
55	
56	    const res = await fetch('/api/clients', {
