  useEffect(() => {
    void load();
  }, []);

  async function remove(projectId: number) {
    const res = await fetch(`/api/projects/${projectId}`, { method: 'DELETE' });
    if (!res.ok) {
      return;
    }
    if (openProjectId === projectId) {
